#include <iostream>
using namespace std;

int a[20010];

int main() {
    int n;
    cin >> n;
    for (int i = 0; i < n; ++i)
        cin >> a[i];
    int S = a[0];
    for (int i = 1; i < n; ++i)
        S &= a[i];
    int ans = 0;
    while (S > 0) {
        if (S & 1) ans++;
        S >>= 1;
    }
    cout << ans;
    return 0;
}

#include <iostream>
#include <string>
using namespace std;

int main() {
    string s = "";
    getline(cin, s);

    for (int k = 1;; ++k) {
        string spaces = "";
        for (int i = 0; i < k; ++i) {
            spaces += " ";
        }

        int pos = s.find(spaces);
        if (pos < 0 || pos >= s.size()) break;

        for (int i = 0; i < pos; ++i) {
            cout << s[i];
        }
        cout << endl;

        string rest = "";
        for (int i = pos + k; i < s.length(); ++i) {
            rest += s[i];
        }
        s = rest;
    }

    cout << s << endl;
    return 0;
}
